def item_name(item_id: int, protocol: int) -> str:
    """查物品注册名（不含命名空间前缀），未知返回 "item_<id>"。"""
    table = ITEM_NAMES.get(protocol)
    if table is None:
        # 无精确表时就近取不超过该协议的表
        keys = [k for k in ITEM_NAMES if k <= protocol]
        table = ITEM_NAMES.get(max(keys)) if keys else None
    if table is None:
        return f'item_{item_id}'
    return table.get(item_id, f'item_{item_id}')
